Return customers in the order they first appear among recognized purchases. Each result must have the shape `{ customer, units, cost }`, where `units` is the sum of quantities and `cost` is the sum of `quantity * price`.

Each invocation must start with fresh aggregation state. Calling the function earlier must have no effect on a later call, and result objects from different calls must be independent.

Use only standard JavaScript computation; do not access the filesystem, network, clock, randomness, frameworks, or external packages. Export exactly `{ buildCustomerTotals }` using `module.exports`.","reference_code":"function buildCustomerTotals(products, purchases) {
  const productsBySku = new Map();
  for (const product of products) {
    productsBySku.set(product.sku, product);
  }

  const totalsByCustomer = new Map();

  for (const purchase of purchases) {
    const product = productsBySku.get(purchase.sku);
    if (!product) {
      continue;
    }

    let totals = totalsByCustomer.get(purchase.customer);
    if (!totals) {
      totals = { units: 0, cost: 0 };
      totalsByCustomer.set(purchase.customer, totals);
    }

    totals.units += purchase.quantity;
    totals.cost += purchase.quantity * product.price;
  }

  return Array.from(totalsByCustomer, ([customer, totals]) => ({
    customer,
    units: totals.units,
    cost: totals.cost,
  }));
}

module.exports = { buildCustomerTotals };
