{"items":[{"id":"cap-v2-associative_aggregation-javascript-generation-01","test_code":"'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['summarizeReadings']);
const { summarizeReadings } = api;
assert.strictEqual(typeof summarizeReadings, 'function');

assert.deepStrictEqual(summarizeReadings([]), []);

const readings = [
  { region: 'west', metric: 'clicks', amount: 4 },
  { region: 'east', metric: 'sales', amount: 10 },
  { region: 'west', metric: 'views', amount: 7 },
  { region: 'west', metric: 'clicks', amount: 6 },
  { region: 'east', metric: 'sales', amount: -2 },
  { region: 'east', metric: 'clicks', amount: 0 },
];

assert.deepStrictEqual(summarizeReadings(readings), [
  {
    region: 'west',
    readingCount: 3,
    metrics: [
      { metric: 'clicks', total: 10, count: 2 },
      { metric: 'views', total: 7, count: 1 },
    ],
  },
  {
    region: 'east',
    readingCount: 3,
    metrics: [
      { metric: 'sales', total: 8, count: 2 },
      { metric: 'clicks', total: 0, count: 1 },
    ],
  },
]);

assert.deepStrictEqual(summarizeReadings([
  { region: '__proto__', metric: 'constructor', amount: 1.5 },
  { region: '__proto__', metric: 'constructor', amount: 2.5 },
]), [
  {
    region: '__proto__',
    readingCount: 2,
    metrics: [{ metric: 'constructor', total: 4, count: 2 }],
  },
]);

const first = summarizeReadings([
  { region: 'shared', metric: 'a', amount: 2 },
]);
const second = summarizeReadings([
  { region: 'shared', metric: 'b', amount: 9 },
]);

assert.deepStrictEqual(second, [
  {
    region: 'shared',
    readingCount: 1,
    metrics: [{ metric: 'b', total: 9, count: 1 }],
  },
]);

first[0].readingCount = 99;
first[0].metrics[0].total = 99;
first[0].metrics.push({ metric: 'injected', total: 1, count: 1 });
assert.deepStrictEqual(second, [
  {
    region: 'shared',
    readingCount: 1,
    metrics: [{ metric: 'b', total: 9, count: 1 }],
  },
]);

assert.deepStrictEqual(summarizeReadings([
  { region: 'shared', metric: 'a', amount: 2 },
]), [
  {
    region: 'shared',
    readingCount: 1,
    metrics: [{ metric: 'a', total: 2, count: 1 }],
  },
]);
