const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['buildCustomerTotals']);
const { buildCustomerTotals } = api;
assert.strictEqual(typeof buildCustomerTotals, 'function');

assert.deepStrictEqual(buildCustomerTotals([], []), []);
assert.deepStrictEqual(
  buildCustomerTotals([{ sku: 'known', price: 10 }], [
    { customer: 'ignored-first', sku: 'missing', quantity: 50 },
  ]),
  [],
);

const products = [
  { sku: 'pen', price: 3 },
  { sku: 'book', price: 12.5 },
  { sku: '__proto__', price: 2 },
];
const purchases = [
  { customer: 'ghost', sku: 'absent', quantity: 100 },
  { customer: 'Bob', sku: 'book', quantity: 2 },
  { customer: 'Ada', sku: 'pen', quantity: 4 },
  { customer: 'Bob', sku: 'pen', quantity: 3 },
  { customer: 'Ada', sku: 'absent', quantity: 9 },
  { customer: 'Ada', sku: '__proto__', quantity: 5 },
  { customer: 'Zero', sku: 'pen', quantity: 0 },
];

assert.deepStrictEqual(buildCustomerTotals(products, purchases), [
  { customer: 'Bob', units: 5, cost: 34 },
  { customer: 'Ada', units: 9, cost: 22 },
  { customer: 'Zero', units: 0, cost: 0 },
]);

const first = buildCustomerTotals(
  [{ sku: 'x', price: 4 }],
  [{ customer: 'C', sku: 'x', quantity: 2 }],
);
const second = buildCustomerTotals(
  [{ sku: 'x', price: 7 }],
  [{ customer: 'C', sku: 'x', quantity: 3 }],
);

assert.deepStrictEqual(first, [{ customer: 'C', units: 2, cost: 8 }]);
assert.deepStrictEqual(second, [{ customer: 'C', units: 3, cost: 21 }]);
assert.notStrictEqual(first, second);
assert.notStrictEqual(first[0], second[0]);

first[0].units = 999;
first[0].cost = 999;
assert.deepStrictEqual(second, [{ customer: 'C', units: 3, cost: 21 }]);
assert.deepStrictEqual(buildCustomerTotals(
  [{ sku: 'x', price: 4 }],
  [{ customer: 'C', sku: 'x', quantity: 2 }],
), [{ customer: 'C', units: 2, cost: 8 }]);
