const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['encodePacket']);
const { encodePacket } = api;
assert.strictEqual(typeof encodePacket, 'function');

const emptyPayload = new Uint8Array(0);
const emptyPacket = { channel: 0, acknowledged: false, encrypted: false, payload: emptyPayload };
const emptyEncoded = encodePacket(emptyPacket);
assert.ok(emptyEncoded instanceof Uint8Array);
assert.deepStrictEqual(Array.from(emptyEncoded), [0, 0, 0]);
assert.notStrictEqual(emptyEncoded.buffer, emptyPayload.buffer);

const payload = new Uint8Array([0x00, 0x01, 0x7f, 0x80, 0xff, 0xa5]);
const payloadSnapshot = Array.from(payload);
const packet = {
  channel: 31,
  acknowledged: true,
  encrypted: true,
  payload,
};
const encoded = encodePacket(packet);

assert.ok(encoded instanceof Uint8Array);
assert.deepStrictEqual(Array.from(encoded), [
  0x7f,
  0x06,
  0x00,
  0x02,
  0xfe,
  0x01,
  0xff,
  0x4b,
  0x30,
]);
assert.deepStrictEqual(Array.from(payload), payloadSnapshot);
assert.deepStrictEqual(packet, {
  channel: 31,
  acknowledged: true,
  encrypted: true,
  payload,
});
assert.notStrictEqual(encoded.buffer, payload.buffer);
assert.strictEqual(encoded[0] & 0x80, 0);

payload[0] = 255;
assert.strictEqual(encoded[2], 0);
encoded[3] = 200;
assert.strictEqual(payload[1], 1);

assert.deepStrictEqual(
  Array.from(encodePacket({
    channel: 5,
    acknowledged: true,
    encrypted: false,
    payload: new Uint8Array([0x81]),
  })),
  [0x25, 0x01, 0x03, 0x27],
);
assert.deepStrictEqual(
  Array.from(encodePacket({
    channel: 16,
    acknowledged: false,
    encrypted: true,
    payload: new Uint8Array([0x40]),
  })),
  [0x50, 0x01, 0x80, 0xd1],
);

const maxPayload = new Uint8Array(255);
for (let i = 0; i < maxPayload.length; i += 1) {
  maxPayload[i] = i;
}
const maxSnapshot = Array.from(maxPayload);
const maxEncoded = encodePacket({
  channel: 31,
  acknowledged: false,
  encrypted: false,
  payload: maxPayload,
});
assert.strictEqual(maxEncoded.length, 258);
assert.strictEqual(maxEncoded[0], 31);
assert.strictEqual(maxEncoded[1], 255);
assert.strictEqual(maxEncoded[2], 0);
assert.strictEqual(maxEncoded[3], 2);
assert.strictEqual(maxEncoded[129], 254);
assert.strictEqual(maxEncoded[130], 1);
assert.strictEqual(maxEncoded[256], 253);
let checksum = 0;
for (let i = 0; i < maxEncoded.length - 1; i += 1) {
  checksum ^= maxEncoded[i];
}
assert.strictEqual(maxEncoded[maxEncoded.length - 1], checksum);
assert.deepStrictEqual(Array.from(maxPayload), maxSnapshot);
assert.notStrictEqual(maxEncoded.buffer, maxPayload.buffer);

const stableInput = {
  channel: 2,
  acknowledged: false,
  encrypted: false,
  payload: new Uint8Array([3]),
};
const first = encodePacket(stableInput);
const second = encodePacket(stableInput);
assert.deepStrictEqual(first, second);
assert.notStrictEqual(first, second);
assert.notStrictEqual(first.buffer, second.buffer);
first[0] = 99;
assert.strictEqual(second[0], 2);
