{"items":[{"id":"cap-v2-binary_and_bitwise-javascript-generation-02","test_code":"'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['encodeMaskedFrame']);
const { encodeMaskedFrame } = api;
assert.strictEqual(typeof encodeMaskedFrame, 'function');

function expectedFrame(payload, options) {
  const frame = new Uint8Array(payload.length + 3);
  frame[0] = options.channel | (options.urgent ? 0x10 : 0) | (options.compressed ? 0x20 : 0);
  frame[1] = payload.length;
  for (let i = 0; i < payload.length; i += 1) {
    frame[i + 2] = payload[i] ^ 0xa5;
  }
  let checksum = 0;
  for (let i = 0; i < frame.length - 1; i += 1) checksum ^= frame[i];
  frame[frame.length - 1] = checksum;
  return frame;
}

{
  const payload = new Uint8Array(0);
  const options = { channel: 0, urgent: false, compressed: false };
  const result = encodeMaskedFrame(payload, options);
  assert.ok(result instanceof Uint8Array);
  assert.deepStrictEqual(result, new Uint8Array([0x00, 0x00, 0x00]));
}

{
  const payload = new Uint8Array([0x00, 0xa5, 0xff, 0x5a]);
  const options = { channel: 9, urgent: true, compressed: false };
  const payloadBefore = payload.slice();
  const optionsBefore = { ...options };
  const result = encodeMaskedFrame(payload, options);
  assert.deepStrictEqual(result, expectedFrame(payloadBefore, optionsBefore));
  assert.strictEqual(result[0], 0x19);
  assert.strictEqual(result[0] & 0xc0, 0);
  assert.deepStrictEqual(payload, payloadBefore);
  assert.deepStrictEqual(options, optionsBefore);

  const resultBefore = result.slice();
  payload[0] = 0xee;
  assert.deepStrictEqual(result, resultBefore);
  result[3] = 0x44;
  assert.strictEqual(payload[1], 0xa5);
  assert.notStrictEqual(result.buffer, payload.buffer);
}

{
  const payload = new Uint8Array([1, 2, 3]);
  const result = encodeMaskedFrame(payload, { channel: 15, urgent: true, compressed: true });
  assert.deepStrictEqual(result, expectedFrame(payload, { channel: 15, urgent: true, compressed: true }));
  assert.strictEqual(result[0], 0x3f);
}

{
  const payload = new Uint8Array(255);
  for (let i = 0; i < payload.length; i += 1) payload[i] = i;
  const before = payload.slice();
  const options = Object.freeze({ channel: 15, urgent: false, compressed: true });
  const result = encodeMaskedFrame(payload, options);
  assert.strictEqual(result.length, 258);
  assert.strictEqual(result[1], 255);
  assert.deepStrictEqual(result, expectedFrame(before, options));
  assert.deepStrictEqual(payload, before);
}
