const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['decodeHexPacket']);
const { decodeHexPacket } = api;
assert.strictEqual(typeof decodeHexPacket, 'function');

function packetHex(payload) {
  const bytes = [payload.length, ...payload];
  let checksum = 0;
  for (const byte of bytes) checksum ^= byte;
  bytes.push(checksum);
  return bytes.map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

function expectError(input, Constructor, message) {
  assert.throws(() => decodeHexPacket(input), (error) => {
    assert.ok(error instanceof Constructor);
    assert.strictEqual(error.message, message);
    return true;
  });
}

assert.deepStrictEqual(decodeHexPacket('0000'), new Uint8Array(0));
assert.deepStrictEqual(decodeHexPacket('0301A5fF58'), new Uint8Array([0x01, 0xa5, 0xff]));
assert.deepStrictEqual(decodeHexPacket(packetHex([0, 16, 127, 128, 255])), new Uint8Array([0, 16, 127, 128, 255]));

expectError(undefined, TypeError, 'hex must be a string');
expectError(null, TypeError, 'hex must be a string');
expectError(new String('0000'), TypeError, 'hex must be a string');
expectError('', Error, 'malformed hexadecimal packet');
expectError('000', Error, 'malformed hexadecimal packet');
expectError('00xz', Error, 'malformed hexadecimal packet');
expectError('00 00', Error, 'malformed hexadecimal packet');
expectError('0100', Error, 'packet length mismatch');
expectError('000000', Error, 'packet length mismatch');
expectError('02010200', Error, 'checksum mismatch');

{
  const payload = Array.from({ length: 255 }, (_, i) => i);
  const decoded = decodeHexPacket(packetHex(payload));
  assert.ok(decoded instanceof Uint8Array);
  assert.strictEqual(decoded.length, 255);
  assert.deepStrictEqual(decoded, new Uint8Array(payload));
}

{
  const first = decodeHexPacket(packetHex([4, 5, 6]));
  const second = decodeHexPacket(packetHex([4, 5, 6]));
  assert.notStrictEqual(first, second);
  assert.notStrictEqual(first.buffer, second.buffer);
  first[0] = 99;
  assert.deepStrictEqual(second, new Uint8Array([4, 5, 6]));
}
