const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['decodeUnsignedVarint']);
const { decodeUnsignedVarint } = api;
assert.strictEqual(typeof decodeUnsignedVarint, 'function');

function encode(value) {
  const result = [];
  do {
    let byte = value % 128;
    value = Math.floor(value / 128);
    if (value !== 0) byte |= 0x80;
    result.push(byte);
  } while (value !== 0);
  return new Uint8Array(result);
}

function malformed(values) {
  assert.throws(
    () => decodeUnsignedVarint(new Uint8Array(values)),
    (error) => error instanceof Error && error.message === 'malformed varint'
  );
}

for (const value of [0, 1, 2, 126, 127, 128, 129, 255, 300, 16383, 16384, 0x0fffffff, 0x10000000, 0xffffffff]) {
  assert.strictEqual(decodeUnsignedVarint(encode(value)), value);
}

assert.throws(
  () => decodeUnsignedVarint([0]),
  (error) => error instanceof TypeError && error.message === 'bytes must be a Uint8Array'
);
assert.throws(
  () => decodeUnsignedVarint(new Uint8Array(0).buffer),
  (error) => error instanceof TypeError && error.message === 'bytes must be a Uint8Array'
);

malformed([]);
malformed([0x80]);
malformed([0x80, 0x80]);
malformed([0x80, 0x80, 0x80, 0x80, 0x80]);
malformed([0x80, 0x80, 0x80, 0x80, 0x80, 0x00]);
malformed([0x00, 0x00]);
malformed([0x01, 0x80]);
malformed([0x80, 0x00]);
malformed([0x81, 0x00]);
malformed([0xff, 0x00]);
malformed([0xff, 0xff, 0xff, 0xff, 0x00]);
malformed([0xff, 0xff, 0xff, 0xff, 0x10]);
malformed([0xff, 0xff, 0xff, 0xff, 0x8f]);

{
  const bytes = new Uint8Array([0xac, 0x02]);
  const before = bytes.slice();
  assert.strictEqual(decodeUnsignedVarint(bytes), 300);
  assert.deepStrictEqual(bytes, before);
}
