const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Object.keys(api), ['runPipeline']);
const { runPipeline } = api;
assert.strictEqual(typeof runPipeline, 'function');

(async () => {
  {
    let calls = 0;
    runPipeline([], 'seed', (error, value) => {
      calls += 1;
      assert.strictEqual(error, null);
      assert.strictEqual(value, 'seed');
    });
    assert.strictEqual(calls, 1);
  }

  {
    const order = [];
    const steps = Object.freeze([
      (value, next) => { order.push(['a', value]); next(null, value + 2); },
      (value, next) => { order.push(['b', value]); next(null, value * 3); },
      (value, next) => { order.push(['c', value]); next(null, String(value)); }
    ]);
    let calls = 0;
    runPipeline(steps, 4, (error, value) => {
      calls += 1;
      assert.strictEqual(error, null);
      assert.strictEqual(value, '18');
    });
    assert.deepStrictEqual(order, [['a', 4], ['b', 6], ['c', 18]]);
    assert.strictEqual(calls, 1);
  }

  {
    const failure = new Error('reported failure');
    let reached = false;
    let calls = 0;
    runPipeline([
      (value, next) => next(failure),
      () => { reached = true; }
    ], 0, (error) => {
      calls += 1;
      assert.strictEqual(error, failure);
    });
    assert.strictEqual(reached, false);
    assert.strictEqual(calls, 1);
  }

  {
    const failure = new Error('thrown failure');
    let reached = false;
    let calls = 0;
    runPipeline([
      () => { throw failure; },
      () => { reached = true; }
    ], 0, (error) => {
      calls += 1;
      assert.strictEqual(error, failure);
    });
    assert.strictEqual(reached, false);
    assert.strictEqual(calls, 1);
  }

  {
    const ignored = new Error('second callback');
    let calls = 0;
    runPipeline([
      (value, next) => { next(null, value + 1); next(ignored); },
      (value, next) => { next(null, value + 1); next(null, 999); }
    ], 10, (error, value) => {
      calls += 1;
      assert.strictEqual(error, null);
      assert.strictEqual(value, 12);
    });
    assert.strictEqual(calls, 1);
  }

  {
    const ignoredThrow = new Error('after next');
    let calls = 0;
    runPipeline([
      (value, next) => { next(null, value + 1); throw ignoredThrow; },
      (value, next) => next(null, value * 2)
    ], 5, (error, value) => {
      calls += 1;
      assert.strictEqual(error, null);
      assert.strictEqual(value, 12);
    });
    assert.strictEqual(calls, 1);
  }

  await new Promise((resolve, reject) => {
    const order = [];
    let calls = 0;
    runPipeline([
      (value, next) => {
        order.push('start-1');
        queueMicrotask(() => { order.push('end-1'); next(null, value + 3); });
      },
      (value, next) => {
        order.push('step-2');
        queueMicrotask(() => next(null, value * 4));
      }
    ], 2, (error, value) => {
      try {
        calls += 1;
        assert.strictEqual(error, null);
        assert.strictEqual(value, 20);
        assert.deepStrictEqual(order, ['start-1', 'end-1', 'step-2']);
        queueMicrotask(() => {
          try { assert.strictEqual(calls, 1); resolve(); } catch (e) { reject(e); }
        });
      } catch (e) {
        reject(e);
      }
    });
    assert.deepStrictEqual(order, ['start-1']);
  });
})().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
